ON CONFLICT (id) DO UPDATE SET recipe_id = EXCLUDED.recipe_id, step_number = EXCLUDED.step_number, instruction = EXCLUDED.instruction, duration_minutes = EXCLUDED.duration_minutes;

-- Validation checks: these raise an exception if the generated seed is structurally inconsistent.
DO $$
BEGIN
    IF EXISTS (SELECT canonical_name FROM ingredients GROUP BY canonical_name HAVING COUNT(*) > 1) THEN RAISE EXCEPTION 'Duplicate ingredients detected'; END IF;
    IF EXISTS (SELECT slug FROM ingredients GROUP BY slug HAVING COUNT(*) > 1) THEN RAISE EXCEPTION 'Duplicate ingredient slugs detected'; END IF;
    IF EXISTS (SELECT 1 FROM ingredient_aliases ia LEFT JOIN ingredients i ON i.id = ia.ingredient_id WHERE i.id IS NULL) THEN RAISE EXCEPTION 'Orphan ingredient aliases detected'; END IF;
    IF EXISTS (SELECT 1 FROM ingredient_prices ip LEFT JOIN ingredients i ON i.id = ip.ingredient_id WHERE i.id IS NULL) THEN RAISE EXCEPTION 'Orphan ingredient prices detected'; END IF;
    IF EXISTS (SELECT 1 FROM barcode_products bp WHERE bp.ingredient_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ingredients i WHERE i.id = bp.ingredient_id)) THEN RAISE EXCEPTION 'Orphan barcode products detected'; END IF;
    IF EXISTS (SELECT 1 FROM recipes r WHERE r.id IN (SELECT id FROM recipes WHERE source = 'PlatePilot generated from public food references') AND NOT EXISTS (SELECT 1 FROM recipe_ingredients ri WHERE ri.recipe_id = r.id)) THEN RAISE EXCEPTION 'Seed recipe without ingredients detected'; END IF;
    IF EXISTS (SELECT 1 FROM recipes r WHERE r.id IN (SELECT id FROM recipes WHERE source = 'PlatePilot generated from public food references') AND NOT EXISTS (SELECT 1 FROM recipe_steps rs WHERE rs.recipe_id = r.id)) THEN RAISE EXCEPTION 'Seed recipe without steps detected'; END IF;
END $$;

COMMIT;
